local NewViewBaseLayer = require("hall.NewViewBaseLayer")
local UDScoreRecord = class("UDScoreRecord", NewViewBaseLayer)
local GetGameName = require("hall.familyCircle.GetGameName")
local EVENTNAME = {
	SELECT_POINT_CHANGE_HISTORY = "/selectPointChangeHistory",
}

function UDScoreRecord:ctor(family_id, click_playerId)
    self.family_id = family_id
    self.click_playerId = click_playerId
    local csbPath = "hall/res/FriendScircle/PartnerManagement/UDScoreRecord.csb"
    UDScoreRecord.super.ctor(self, csbPath)
    self:enableMask(true)

    --add by zzy
    self.AllHeHuoRenList = {}
	self.allPartnerList = {}

    self.curPage = 1
	self.page_num = 7
    self.tatolPage = 1
    self.item:hide()
    self:initEvent()
    self:createTableView()
    self:InitGame(self.curPage, self.click_playerId)
end
function UDScoreRecord:initEvent()
	
    ReqMgr:addHandle("UDScoreRecord", EVENTNAME)
    self.r_page:onClick(handler(self, self.btn_r_page))
	self.l_page:onClick(handler(self, self.btn_l_page))
end

function UDScoreRecord:onExit()
    ReqMgr:delHandle("UDScoreRecord", EVENTNAME)
end
--test
function UDScoreRecord:createTableView()
    self.ListView:hide()
	local size = self.ListView:getSize()
	local getPosition = self.ListView:getPosition()
	local getAnchorPoint = self.ListView:getAnchorPoint()
    self.userList = cc.TableView:create(size)
    self.userList:addTo(self.root)
    self.userList:setDirection(cc.SCROLLVIEW_DIRECTION_VERTICAL)
    self.userList:setVerticalFillOrder(cc.TABLEVIEW_FILL_TOPDOWN)
    self.userList:setAnchorPoint(getAnchorPoint)
    self.userList:setPosition(getPosition)
    self.userList:setDelegate()


    self.userList:registerScriptHandler(handler(self, self.tableCellAtIndex), cc.TABLECELL_SIZE_AT_INDEX)
    self.userList:registerScriptHandler(handler(self, self.tableCellTouched), cc.TABLECELL_TOUCHED)
    self.userList:registerScriptHandler(handler(self, self.cellSizeForTable), cc.TABLECELL_SIZE_FOR_INDEX)
    self.userList:registerScriptHandler(handler(self, self.numberOfCellsInTableView), cc.NUMBER_OF_CELLS_IN_TABLEVIEW)
    self.userList:reloadData()
end

--test
function UDScoreRecord:tableCellAtIndex(view, idx)
    local cell = view:dequeueCell()
    local item = nil
    if nil == cell then
        cell = cc.TableViewCell:new()
        local userBar = self:createUser(self.AllHeHuoRenList[idx+1], idx + 1)
        cell:addChild(userBar)
    else
        local node = cell:getChildByName("playerNode")
        self:initCellInfo(node,self.AllHeHuoRenList[idx+1], idx + 1)
    end
    return cell
end

function UDScoreRecord:initCellInfo(tempRoot,userItem,index)
    local changeTime = os.date("%m-%d %H:%M:%S", userItem.changeTime/1000)
    local changePoint = tonumber(userItem.changePoint) or 0
    local nowPoint = tonumber(userItem.nowPoint) or 0
    changePoint = changePoint / 100
    nowPoint = nowPoint / 100
    local gameName = GetGameName:getName(userItem.operator)
    if gameName == "" then
        gameName = userItem.operator or ""
       
    end
    
    local activityId = userItem.activityId or ""
    if userItem.type == 1 then
        activityId = "上下分"
    elseif userItem.type == 3 then
        activityId = "被抽水"
    elseif userItem.type == 4 then
        activityId = "仓库存储"
    elseif userItem.type == 5 then
        activityId = "赠送"
    elseif userItem.type == 6 then
        activityId = "百人场"
    else
    end

    tempRoot.txt_gameName:setString(gameName)
    tempRoot.txt_id:setString(activityId)
    tempRoot.txt_uid:setString(userItem.uid or "")
    tempRoot.txt_score:setString(changePoint)
    tempRoot.txt_nowScore:setString(nowPoint)
    tempRoot.txt_time:setString(changeTime)

end

--test
function UDScoreRecord:createUser(userItem, index)
    local item = self.item:clone()
    item:show()
    item:setName("playerNode")
    GameUtils.setNodeNameBindObj(item)
    self:initCellInfo(item,userItem, index)
    local size = item:getContentSize()
    item:setPosition(0, 0)
    return item
end

function UDScoreRecord:tableCellTouched(view, cell)
end

function UDScoreRecord:cellSizeForTable()
    local size = self.item:getContentSize()
    return size.width, size.height
end

function UDScoreRecord:numberOfCellsInTableView()
    if not (self and self.AllHeHuoRenList) then return end
    return #self.AllHeHuoRenList or 0
end


function UDScoreRecord:InitGame(page, playerId)
	page = page or 1
    local data = {
        groupId = self.family_id, 
        XYUid = USER_INFO.uid, 
        pageSize = self.page_num, 
        currentPage = page
    }
    if tonumber(playerId) then
        data["searchId"] = tonumber(playerId)
    end
    ReqMgr:request(EVENTNAME.SELECT_POINT_CHANGE_HISTORY, data, handler(self , self.SELECT_POINT_CHANGE_HISTORY), {page = page})
end

function UDScoreRecord:SELECT_POINT_CHANGE_HISTORY(event)
    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end
    self.AllHeHuoRenList = {}
    self.AllHeHuoRenList = data.list
	self.allPartnerList = data

    self.tatolPage = math.ceil(data.listCount / self.page_num)
	if self.tatolPage == 0 then
        self.tatolPage = 1
    end
	self.curPage = param.page
    self.r_text:setString(self.curPage.."/"..self.tatolPage)
    self:FlushPartnerList_new(data)
end

function UDScoreRecord:FlushPartnerList_new(data)
    if not data.list then return end
    self.userList:reloadData()
end

function UDScoreRecord:onClickBtnReturn(...)
    self:removeSelf()
end

function UDScoreRecord:btn_r_page()
	local page = self.curPage + 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page, self.click_playerId)
end

function UDScoreRecord:btn_l_page()
	local page = self.curPage - 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page, self.click_playerId)
end

return UDScoreRecord